def transform(grid):
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pts = {(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg}
    components = []
    while pts:
        start = pts.pop()
        comp = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                p = (r+dr, c+dc)
                if p in pts:
                    pts.remove(p)
                    comp.add(p)
                    q.append(p)
        components.append(comp)
    shape = max(components, key=len)
    shape_color = grid[next(iter(shape))[0]][next(iter(shape))[1]]
    r0 = min(r for r,c in shape); r1 = max(r for r,c in shape)
    c0 = min(c for r,c in shape); c1 = max(c for r,c in shape)
    sh, sw = r1-r0+1, c1-c0+1
    scatter = [p for comp in components if comp is not shape for p in comp]
    anchor = next(p for p in scatter if grid[p[0]][p[1]] == shape_color)
    other = next(grid[r][c] for r,c in scatter if grid[r][c] != shape_color)
    out = [[bg]*w for _ in range(h)]
    def paint(top, left, color):
        for r,c in shape:
            rr, cc = top+r-r0, left+c-c0
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    paint(r0, c0, other)
    ar, ac = anchor
    for r,c in scatter:
        if grid[r][c] == other:
            paint(r0 + ((r-ar)//2)*sh, c0 + ((c-ac)//2)*sw, shape_color)
    return out
